ALTER POLICY trend_videos_storage_read ON storage.objects TO authenticated USING (bucket_id = 'trend-videos' AND (owner_id = (SELECT auth.uid()::text) OR EXISTS (SELECT 1 FROM public.trend_videos v WHERE v.video_url = objects.name OR v.audio_path = objects.name)));
ALTER POLICY social_chat_media_read ON storage.objects TO authenticated USING (bucket_id = 'social-stories' AND (EXISTS (SELECT 1 FROM public.social_messages m JOIN public.social_conversations c ON c.id = m.conversation_id WHERE m.media_path = objects.name AND (SELECT auth.uid()) IN (c.member_a, c.member_b)) OR EXISTS (SELECT 1 FROM public.social_group_messages m JOIN public.social_group_members gm ON gm.group_id = m.group_id WHERE m.media_path = objects.name AND gm.user_id = (SELECT auth.uid()))));